// bool InUseDof (Parm, ZeroConstructor, IsPlainOldData, NoDestructor, HasGetValueTypeHash, NativeAccessSpecifierPublic)

void UClientGameSetting::SetUseDof(bool InUseDof)
{
	static class UFunction* Func = nullptr;

	if (Func == nullptr)
		Func = Class->GetFunction("ClientGameSetting", "SetUseDof");

	Params::UClientGameSetting_SetUseDof Parms{};

	Parms.InUseDof = InUseDof;

	auto Flgs = Func->FunctionFlags;
	Func->FunctionFlags |= 0x400;

	UObject::ProcessEvent(Func, &Parms);

	Func->FunctionFlags = Flgs;
}


